import { Ajv } from "ajv";
import standaloneCode from "ajv/dist/standalone/index.js";
import { z } from "zod";
import { stallionObject } from "./model";

export const jsonSchema = (): Record<string, unknown> =>
  z.toJSONSchema(stallionObject, { target: "draft-07" });

export const validatorSource = (): string => {
  const ajv = new Ajv({ code: { source: true, esm: true }, unicode: false });
  const validate = ajv.compile(jsonSchema());
  return `${standaloneCode(ajv, validate)}\n`;
};

export const validatorTypes = (): string =>
  [
    'import type { ErrorObject } from "ajv";',
    'import type { StallionObject } from "../src/model";',
    "",
    "type Validate = ((data: unknown) => data is StallionObject) & { errors?: ErrorObject[] | null };",
    "",
    "export declare const validate: Validate;",
    "export default validate;",
    "",
  ].join("\n");
import { expect, test } from "vitest";
import { jsonSchema, validatorSource, validatorTypes } from "./generate";

test("checked-in JSON Schema matches the zod models", async () => {
  await expect(`${JSON.stringify(jsonSchema(), null, 2)}\n`).toMatchFileSnapshot(
    "../generated/object.schema.json",
  );
});

test("checked-in validator matches the JSON Schema", async () => {
  await expect(validatorSource()).toMatchFileSnapshot("../generated/validate.js");
  await expect(validatorTypes()).toMatchFileSnapshot("../generated/validate.d.ts");
});
import { readFileSync } from "node:fs";
import { Encoder } from "cbor-x";
import { expect, test } from "vitest";
import { decode, encode } from "./codec";
import type { StallionObject } from "./model";
import { stallionObject } from "./model";

const stroke: StallionObject = {
  type: "Stroke",
  objectId: "stroke-0001",
  nativeZoom: -3,
  bbox: { minX: 10, minY: 12.5, maxX: 42, maxY: 30.25 },
  colour: 0,
  rgb: 0x123456,
  size: "Medium",
  width: 12.5,
  points: [
    [10, 12.5, 0.5],
    [26, 20, 0.75],
    [42, 30.25, 1],
  ],
};

const objects: StallionObject[] = [
  stroke,
  {
    type: "Shape",
    objectId: "shape-0001",
    nativeZoom: 0,
    bbox: { minX: 0, minY: 0, maxX: 256, maxY: 128 },
    colour: 5,
    rgb: 0x8e4ec6,
    size: "Large",
    width: 20,
    shape: "Ellipse",
  },
  {
    type: "Text",
    objectId: "text-0001",
    nativeZoom: 40,
    bbox: { minX: 1, minY: 2, maxX: 3, maxY: 4 },
    colour: 0,
    rgb: 0x1f2328,
    size: "Small",
    width: 3,
    text: "hello",
  },
];

const raw = new Encoder({ useRecords: false, mapsAsObjects: true, variableMapSize: true });

const hex = (bytes: Uint8Array): string =>
  `${Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("")}\n`;

test.each(objects)("round-trips a $type", (object) => {
  expect(stallionObject.parse(object)).toEqual(object);
  expect(decode(encode(object))).toEqual({ ok: true, value: object });
});

test("matches the golden stroke fixture", async () => {
  await expect(hex(encode(stroke))).toMatchFileSnapshot("../fixtures/stroke.cbor.hex");
});

const legacyBytes = (): Uint8Array => {
  const text = readFileSync(new URL("../fixtures/stroke-legacy.cbor.hex", import.meta.url), "utf8");
  return Uint8Array.from(text.trim().match(/../g) ?? [], (pair) => Number.parseInt(pair, 16));
};

test("decodes a legacy stroke without rgb or width and derives both", () => {
  const decoded = decode(legacyBytes());
  expect(decoded).toMatchObject({ ok: true, value: { colour: 2, rgb: 0xf76b15, width: 8 } });
  const legacy = raw.decode(legacyBytes()) as Record<string, unknown>;
  expect(legacy.rgb).toBeUndefined();
  expect(legacy.width).toBeUndefined();
  expect(raw.decode(encode(legacy as unknown as StallionObject))).toMatchObject({
    rgb: 0xf76b15,
    width: 8,
  });
});

test.each([
  ["an rgb above 0xFFFFFF", { ...stroke, rgb: 0x1000000 }],
  ["a negative rgb", { ...stroke, rgb: -1 }],
  ["a width below 0.5", { ...stroke, width: 0.4 }],
  ["a width above 96", { ...stroke, width: 96.5 }],
  ["an infinite width", { ...stroke, width: Number.POSITIVE_INFINITY }],
  ["a NaN width", { ...stroke, width: Number.NaN }],
  ["a colour outside the palette", { ...stroke, colour: 6 }],
  ["a pressure above one", { ...stroke, points: [[0, 0, 1.5]] }],
  ["a zoom level beyond 40", { ...stroke, nativeZoom: 41 }],
  ["an unknown field", { ...stroke, extra: true }],
])("rejects %s", (_, invalid) => {
  expect(stallionObject.safeParse(invalid).success).toBe(false);
  expect(decode(raw.encode(invalid))).toMatchObject({ ok: false });
  expect(() => encode(invalid as unknown as StallionObject)).toThrow(TypeError);
});
export const PALETTE_RGB = [0x1f2328, 0xe5484d, 0xf76b15, 0x30a46c, 0x0090ff, 0x8e4ec6] as const;

export const MAX_RGB = 0xffffff;

export type Coloured = { colour: number; rgb?: number | undefined };

export const rgbOf = ({ colour, rgb }: Coloured): number =>
  rgb ?? PALETTE_RGB[colour] ?? PALETTE_RGB[0];

const channels = (rgb: number): [number, number, number] => [
  (rgb >> 16) & 0xff,
  (rgb >> 8) & 0xff,
  rgb & 0xff,
];

export const nearestColour = (rgb: number): number => {
  const [r, g, b] = channels(rgb);
  let best = 0;
  let bestDistance = Number.POSITIVE_INFINITY;
  PALETTE_RGB.forEach((entry, index) => {
    const [er, eg, eb] = channels(entry);
    const distance = (r - er) ** 2 + (g - eg) ** 2 + (b - eb) ** 2;
    if (distance < bestDistance) {
      best = index;
      bestDistance = distance;
    }
  });
  return best;
};

export const rgbHex = (rgb: number): string => `#${rgb.toString(16).padStart(6, "0")}`;

export const parseRgbHex = (text: string): number | undefined => {
  const match = /^#?([0-9a-f]{6}|[0-9a-f]{3})$/i.exec(text.trim());
  if (!match?.[1]) return undefined;
  const digits = match[1].length === 3 ? [...match[1]].map((d) => d + d).join("") : match[1];
  return Number.parseInt(digits, 16);
};

export const withRgb = <T extends Coloured>(object: T): T & { rgb: number } => ({
  ...object,
  rgb: rgbOf(object),
});




