import type { StoredObject } from "@stallion/client-store";
import type { LiveObjects } from "@stallion/client-sync";
import { afterEach, expect, test, vi } from "vitest";
import { createSurface, INK_ALPHA, PAPER } from "./surface";
import type { Awareness, DrawingSource } from "./sync";

const stored: StoredObject = {
  tile: { level: 0, tx: 0, ty: 0 },
  object: {
    type: "Stroke",
    objectId: "000000000aaaaaaaaaaaa",
    nativeZoom: 0,
    bbox: { minX: 0, minY: 0, maxX: 10, maxY: 10 },
    colour: 0,
    rgb: 0x1f2328,
    size: "Medium",
    points: [
      [1, 1, 0.5],
      [8, 8, 0.5],
    ],
  },
};

afterEach(() => vi.unstubAllGlobals());

const PENCIL = { width: 8, primary: 0, secondary: 4, mode: "Pencil" } as const;

const harness = (initial: StoredObject[], awareness?: Awareness) => {
  const calls: string[] = [];
  const context = {
    setTransform: () => undefined,
    clearRect: () => calls.push("clearRect"),
    fillRect: function (this: { fillStyle: string }) {
      calls.push(`fillRect ${this.fillStyle}`);
    },
    fill: function (this: { fillStyle: string; globalAlpha: number }) {
      calls.push(this.globalAlpha === 1 ? `fill ${this.fillStyle}` : `ink ${this.fillStyle}`);
    },
    fillStyle: "",
    globalAlpha: 1,
  };
  const listen = { addEventListener: () => undefined, removeEventListener: () => undefined };
  vi.stubGlobal("window", { ...listen, devicePixelRatio: 1 });
  vi.stubGlobal("localStorage", { getItem: () => null, setItem: () => undefined });
  const frames: FrameRequestCallback[] = [];
  vi.stubGlobal("requestAnimationFrame", (callback: FrameRequestCallback) => frames.push(callback));
  vi.stubGlobal("cancelAnimationFrame", () => undefined);
  vi.stubGlobal(
    "ResizeObserver",
    class {
      observe() {}
      disconnect() {}
    },
  );
  vi.stubGlobal(
    "Path2D",
    class {
      moveTo() {}
      lineTo() {}
      closePath() {}
    },
  );
  const canvas = {
    ...listen,
    clientWidth: 400,
    clientHeight: 300,
    width: 0,
    height: 0,
    getContext: () => context,
  } as unknown as HTMLCanvasElement;
  const store = new Map(initial.map((entry) => [entry.object.objectId, entry]));
  const observers = new Set<(changed: ReadonlySet<string>) => void>();
  const objects = Object.assign(store, {
    observe(listener: (changed: ReadonlySet<string>) => void) {
      observers.add(listener);
      return () => observers.delete(listener);
    },
  }) as LiveObjects;
  const source: DrawingSource = {
    view: () => undefined,
  if (key === "y" && !event.shiftKey) return "Redo";
  return undefined;
};

const SURFACE_CLASS: Record<ToolMode, string> = {
  Pencil: "surface",
  Pan: "surface panning",
  Eraser: "surface erasing",
  Select: "surface selecting",
};

export function Board({ boardId }: { boardId: string }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [tool, setTool] = useState<Tool>({
    width: PENCIL_PX.Medium,
    primary: PALETTE_RGB[0],
    secondary: PALETTE_RGB[4],
    mode: "Pencil",
  });
  const [error, setError] = useState<string | undefined>(undefined);
  const [connection, setConnection] = useState<Connection>("LocalOnly");
  const [history, setHistory] = useState<HistoryState>(EMPTY_HISTORY);
  const [view, setView] = useState<SurfaceView>(INITIAL_VIEW);
  const [shareOpen, setShareOpen] = useState(false);
  const [presence, setPresence] = useState<Presence>(NO_PRESENCE);
  const [name, setName] = useState(() => storedName(boardId));
  const sourceRef = useRef<BoardSource | undefined>(undefined);
  const surfaceRef = useRef<Surface | undefined>(undefined);
  const toolRef = useRef(tool);
  toolRef.current = tool;
  const closeShare = useCallback(() => setShareOpen(false), []);
  const checkAuthExpired = useCallback(async () => {
    const result = await myBoardsForPage()?.list();
    return (
      result !== undefined &&
      !result.ok &&
      (result.reason === "AuthRedirect" ||
        result.reason === "Http401" ||
        result.reason === "Http403")
    );
  }, []);

