import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { homedir } from "node:os";
import { chromium, devices } from "playwright";
import { routeAccessHeaders } from "../npm-scripts/env.mjs";

const ORIGIN = "https://stallion.matthijs-f49.workers.dev";
const OUT = join(homedir(), "development", ".tmp", "stallion-styles");
const LEGACY = "cagl5toewxf62ts2fn43id996";
const PROFILES = [
  { name: "phone", device: "Pixel 7" },
  { name: "tablet", device: "Galaxy Tab S9" },
];

const boardId = () => {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  let value = 0n;
  for (const byte of bytes) value = (value << 8n) | BigInt(byte);
  return value.toString(36).padStart(25, "0");
};

const draw = async (page, points) => {
  const cdp = await page.context().newCDPSession(page);
  const touch = (type, p) =>
    cdp.send("Input.dispatchTouchEvent", {
      type,
      touchPoints: p ? [{ x: p.x, y: p.y, id: 1, radiusX: 2, radiusY: 2 }] : [],
    });
  const [first, ...rest] = points;
  await touch("touchStart", first);
  for (const p of rest) await touch("touchMove", p);
  await touch("touchEnd");
  await cdp.detach();
};

const wave = (x0, x1, y, amp) =>
  Array.from({ length: 32 }, (_, i) => {
    const t = i / 31;
    return { x: x0 + (x1 - x0) * t, y: y + Math.sin(t * Math.PI * 2) * amp };
  });

const watch = (page) => {
  const problems = [];
  page.on("console", (m) => {
    if (m.type() === "error") problems.push(`console: ${m.text()}`);
  });
  page.on("pageerror", (e) => problems.push(`pageerror: ${e.message}`));
  return problems;
};

const browser = await chromium.launch({ headless: true });
const report = [];
try {
  for (const profile of PROFILES) {
    const context = await browser.newContext({ ...devices[profile.device], colorScheme: "light" });
    await routeAccessHeaders(context, ORIGIN);
    const page = await context.newPage();
    const problems = watch(page);
    await page.goto(`${ORIGIN}/b/${boardId()}`, { waitUntil: "load" });
    await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
    await page.waitForTimeout(800);
    const { width: w, height: h } = page.viewportSize();
    const strokes = [
      { style: "Pen", colour: "Colour 1", points: wave(w * 0.15, w * 0.85, h * 0.32, 30) },
      {
        style: "Highlighter",
        colour: "Colour 3",
        points: wave(w * 0.2, w * 0.8, h * 0.36, -40),
      },
      { style: "Dashed", colour: "Colour 5", points: wave(w * 0.15, w * 0.85, h * 0.52, 30) },
      { style: "Uniform", colour: "Colour 4", points: wave(w * 0.15, w * 0.85, h * 0.7, 30) },
    ];
    for (const stroke of strokes) {
      const more = page.getByRole("button", { name: "More tools" });
      if (await more.isVisible()) await more.tap();
      await page.locator("[data-toolbar-flip]").tap();
      const palette = page.locator('.toolbar[data-layout="Palette"]');
      await palette.waitFor({ state: "visible", timeout: 5000 });
      await palette.getByRole("button", { name: `${stroke.style} style` }).tap();
      await palette.getByRole("button", { name: stroke.colour }).tap();
      await palette.getByRole("button", { name: "Large pencil" }).tap();
      if (stroke.style === "Pen") {
        writeFileSync(join(OUT, `${profile.name}-palette.png`), await page.screenshot());
      }
      await page.locator("[data-toolbar-flip]").tap();
      await page.waitForTimeout(300);
      await draw(page, stroke.points);
      await page.waitForTimeout(500);
    }
    await page.waitForTimeout(1000);
    writeFileSync(join(OUT, `${profile.name}-styles.png`), await page.screenshot());
    await page.reload({ waitUntil: "load" });
    await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
    await page.waitForTimeout(2000);
    writeFileSync(join(OUT, `${profile.name}-styles-reloaded.png`), await page.screenshot());
    await page.goto(`${ORIGIN}/b/${LEGACY}`, { waitUntil: "load" });
    await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
    await page.waitForTimeout(3000);
    writeFileSync(join(OUT, `${profile.name}-legacy-board.png`), await page.screenshot());
    report.push({ profile: profile.name, consoleErrors: problems.length, problems });
    await context.close();
  }
} finally {
  await browser.close();
}
console.log(JSON.stringify(report, null, 2));
